local function fallbackBase64Decode(encoded)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}

    for index = 1, #alphabet do
        lookup[string.byte(alphabet, index)] = index - 1
    end

    local clean = string.gsub(encoded, "%s", "")
    local padding = clean:sub(-2) == "==" and 2 or (clean:sub(-1) == "=" and 1 or 0)
    local outputLength = math.floor(#clean / 4) * 3 - padding
    local output = buffer.create(outputLength)
    local outputOffset = 0

    for inputOffset = 1, #clean, 4 do
        local first = lookup[string.byte(clean, inputOffset)]
        local second = lookup[string.byte(clean, inputOffset + 1)]
        local thirdByte = string.byte(clean, inputOffset + 2)
        local fourthByte = string.byte(clean, inputOffset + 3)
        local third = thirdByte == 61 and 0 or lookup[thirdByte]
        local fourth = fourthByte == 61 and 0 or lookup[fourthByte]

        assert(first and second and third and fourth, "invalid base64 data")

        local packed = first * 0x40000 + second * 0x1000 + third * 0x40 + fourth
        if outputOffset < outputLength then
            buffer.writeu8(output, outputOffset, bit32.rshift(packed, 16))
            outputOffset += 1
        end
        if outputOffset < outputLength then
            buffer.writeu8(output, outputOffset, bit32.band(bit32.rshift(packed, 8), 0xff))
            outputOffset += 1
        end
        if outputOffset < outputLength then
            buffer.writeu8(output, outputOffset, bit32.band(packed, 0xff))
            outputOffset += 1
        end
    end

    return buffer.tostring(output)
end

