    if selectFunction("#", ...) ~= 0 then
        return originalGetCameraData(receiver, ...)
    end

    local targetPart = silentTarget.part
    if not targetPart or not silentEnabledOption.Value then
        return originalGetCameraData(receiver, ...)
    end

    local chanceValue = hitChanceOption.Value
    if chanceValue < randomInteger(0, 99) then
        return originalGetCameraData(receiver, ...)
    end
    if not silentActivationState:GetState() then
        return originalGetCameraData(receiver, ...)
    end

    local packedCameraResults = packResults(originalGetCameraData(receiver, ...))
    local cameraData = makeCameraData("CameraData", packedCameraResults[1])
    local cameraFrame = cameraData:GetCameraCFrame()
    local muzzleFrame = cameraData:GetMuzzleCFrame()
    local manipulation = manipulationState.data
    local equippedItem = playerState.EquippedItem
    cameraData:SetHitOffset(cframeConstructor(randomClass.new():NextUnitVector() * 0.1))

    if not manipulation then
        local targetPosition = targetPart.Position
        cameraData:SetCameraCFrame(cframeConstructor(cameraFrame.Position, targetPosition))
        cameraData:SetMuzzleCFrame(cframeConstructor(muzzleFrame.Position, targetPosition))
