        local adjustedMuzzleFrame = muzzleFrame
        if manipulation.c1 then
            adjustedCameraFrame = cframeConstructor(manipulation.c1) *
                orientationConstructor(cameraFrame:ToOrientation())
        end
        if manipulation.c2 then
            adjustedMuzzleFrame = cframeConstructor(manipulation.c2) *
                orientationConstructor(muzzleFrame:ToOrientation())
        end
        if manipulation.offset then
            adjustedMuzzleFrame = adjustedMuzzleFrame + manipulation.offset
            adjustedCameraFrame = adjustedCameraFrame + manipulation.offset
        end
        cameraData:SetCameraCFrame(adjustedCameraFrame)
        cameraData:SetMuzzleCFrame(adjustedMuzzleFrame)
        if manipulation.h_offset then
            cameraData:SetHitOffset(cframeConstructor(manipulation.h_offset))
        end
    end

    cameraData:SetHitPart(targetPart)
    return unpackResults(packedCameraResults, 1, packedCameraResults.n)
    end
    return silent_get_camera_data_hook
end

