                                                                                        colorCycleIndex = 0
                                                                                    end
                                                                                    local widthOffset
                                                                                    for _, character in characters do
                                                                                        colorCycleIndex = colorCycleIndex % 3 + 1
                                                                                        local digit = damageDigitTemplate:Clone()
                                                                                        local textLabel = digit.TextLabel
                                                                                        textLabel.TextColor3 = Options[
                                                                                            "hit_effects_col_" .. colorCycleIndex
                                                                                        ].Value
                                                                                        textLabel.Text = character
