                                                                            local function makeCloneHitEffect(
                                                                                cloneCache,
                                                                                currentCamera,
                                                                                readCloneColor,
                                                                                cloneSettings,
                                                                                clonePartNames,
                                                                                runService
                                                                            )
                                                                                local function clearCloneCache(targetModel)
                                                                                    cloneCache[targetModel] = false
                                                                                end
                                                                                return function(hitPart)
                                                                                    if not hitPart then
                                                                                        return
                                                                                    end
                                                                                    local targetModel = hitPart.Parent
                                                                                    if not targetModel then
                                                                                        return
                                                                                    end
                                                                                    if cloneCache[targetModel] then
                                                                                        return
                                                                                    end
                                                                                    local distance = (hitPart.Position - currentCamera.CFrame.Position).Magnitude
                                                                                    if distance > 500 then
                                                                                        return
                                                                                    end
                                                                                    cloneCache[targetModel] = true
                                                                                    local cloneModel = Instance.new("Model", targetModel.Parent)
                                                                                    local clonedParts = {}
                                                                                    local selectedMaterial = Enum.Material[Options.hit_effects_material.Value]
                                                                                    local primaryPart = targetModel.PrimaryPart
                                                                                    local targetChildren = targetModel:GetChildren()
                                                                                    if primaryPart then
                                                                                        table.remove(targetChildren, table.find(targetChildren, primaryPart))
                                                                                    end
                                                                                    local keepAccessories = not cloneSettings.Value["remove accessories from clone"]
                                                                                    for _, targetChild in targetChildren do
                                                                                        if keepAccessories and targetChild.ClassName == "Accessory" then
                                                                                            local accessoryClone = targetChild:Clone()
                                                                                            local handle = accessoryClone:FindFirstChild("Handle")
                                                                                            if handle and handle.Transparency ~= 1 then
                                                                                                handle:ClearAllChildren()
                                                                                                accessoryClone.Parent = cloneModel
                                                                                                handle.Material = Enum.Material.ForceField
                                                                                                handle.CanCollide = false
                                                                                                handle.CanQuery = false
                                                                                                handle.Anchored = true
                                                                                                handle.Color = readCloneColor()
                                                                                                table.insert(clonedParts, handle)
                                                                                            end
                                                                                        elseif table.find(clonePartNames, targetChild.Name) then
                                                                                            local partClone = targetChild:Clone()
                                                                                            partClone:ClearAllChildren()
                                                                                            partClone.Material = selectedMaterial
                                                                                            partClone.Parent = cloneModel
                                                                                            partClone.CanCollide = false
                                                                                            partClone.CanQuery = false
                                                                                            partClone.Anchored = true
                                                                                            partClone.Color = readCloneColor()
                                                                                            table.insert(clonedParts, partClone)
                                                                                        end
                                                                                    end
                                                                                    task.delay(0.15, function()
                                                                                        clearCloneCache(targetModel)
                                                                                    end)
                                                                                    task.wait(1)
                                                                                    local transparency = 0
                                                                                    while transparency < 1 do
                                                                                        transparency += runService.RenderStepped:Wait() * 2
                                                                                        for _, clonedPart in clonedParts do
                                                                                            clonedPart.Transparency = transparency
                                                                                        end
                                                                                    end
                                                                                    table.clear(clonedParts)
                                                                                    cloneModel:Destroy()
                                                                                end
                                                                            end
                                                                            local function makePhantomForcesColorResolver(
                                                                                hitEffectSettings,
                                                                                readSharedIndex,
                                                                                writeSharedIndex,
                                                                                originalColorsByPartName,
                                                                                readColor1,
                                                                                readColor2,
                                                                                readColor3
                                                                            )
                                                                                return function(partName)
                                                                                    local settings = hitEffectSettings.Value
                                                                                    if settings["cycle colors for text"] then
                                                                                        local cycleIndex = readSharedIndex()
                                                                                        cycleIndex = cycleIndex % 3 + 1
                                                                                        writeSharedIndex(cycleIndex)
                                                                                        return Options["hit_effects_col_" .. cycleIndex].Value
                                                                                    end
                                                                                    if settings["original colors | phantom forces"] then
                                                                                        local originalColor = originalColorsByPartName[partName]
                                                                                        if originalColor then
                                                                                            return originalColor
                                                                                        end
                                                                                        return Color3.fromRGB(255, 255, 0)
                                                                                    end
                                                                                    if partName.Head then
                                                                                        return readColor1()
                                                                                    end
                                                                                    if partName.UpperTorso then
                                                                                        return readColor2()
                                                                                    end
                                                                                    return readColor3()
                                                                                end
                                                                            end
                                                                            local function makePhantomForcesHitEffect(
                                                                                damagePartTemplate,
                                                                                resolveTextColor,
                                                                                readSharedIndex,
                                                                                writeSharedIndex
                                                                            )
                                                                                return function(hitPart, damage)
                                                                                    local damagePart = damagePartTemplate:Clone()
                                                                                    local hitCFrame = CFrame.new(hitPart.Position)
                                                                                    damagePart.CFrame = hitCFrame
                                                                                    damagePart.Parent = workspace
                                                                                    local isHead = hitPart.Name == "Head"
                                                                                    local textSize = 20 * (isHead and 1.75 or 1)
                                                                                    local billboard = damagePart.BillboardDamage
                                                                                    local damageText = billboard.TextDamage
                                                                                    damageText.Text = damage
                                                                                    local damageShadow = billboard.TextDamageShadow
                                                                                    damageShadow.Text = damage
                                                                                    damageText.TextSize = textSize
                                                                                    damageShadow.TextSize = textSize
                                                                                    billboard.Adornee = damagePart
                                                                                    billboard.Parent = damagePart
                                                                                    damageText.TextColor3 = resolveTextColor(hitPart.Name)
                                                                                    damageShadow.UIStroke.Thickness = 2
                                                                                    local fontFace = Font.new(
                                                                                        "rbxasset://fonts/families/Zekton.json",
                                                                                        Enum.FontWeight.Regular,
                                                                                        Enum.FontStyle.Italic
                                                                                    )
                                                                                    damageText.FontFace = fontFace
                                                                                    damageShadow.FontFace = fontFace
                                                                                    local angleIndex = readSharedIndex()
                                                                                    local angle = 2.399963229728653 * angleIndex
                                                                                    angleIndex += 1
                                                                                    writeSharedIndex(angleIndex)
                                                                                    local xOffset = 32 * math.cos(angle)
                                                                                    local yOffset = -48 * math.sin(angle) - 90
                                                                                    local destination = UDim2.new(0.5, xOffset, 0.5, yOffset)
                                                                                    damageText:TweenPosition(
                                                                                        destination,
                                                                                        Enum.EasingDirection.Out,
                                                                                        Enum.EasingStyle.Quint,
                                                                                        1,
                                                                                        true
                                                                                    )
                                                                                    damageShadow:TweenPosition(
                                                                                        destination + UDim2.fromOffset(1, 1),
                                                                                        Enum.EasingDirection.Out,
                                                                                        Enum.EasingStyle.Quint,
                                                                                        1,
                                                                                        true
                                                                                    )
                                                                                    task.delay(1, function()
                                                                                        for fadeStep = 1, 10 do
                                                                                            local transparency = fadeStep / 10
                                                                                            billboard.TextDamage.TextTransparency = transparency
                                                                                            billboard.TextDamageShadow.TextTransparency = transparency
                                                                                            task.wait(1 / 60)
                                                                                        end
                                                                                        billboard:Destroy()
                                                                                    end)
                                                                                end
                                                                            end
                                                                            local function cloneNamedBaseParts(source, output, predicate)
